const active=page=>page.locator('#modal-root>[data-surface-state=active]');
async function startRoom(page,game){await page.locator('[data-start="'+game+'"]').click();await active(page).locator('[data-game-mode=hotseat]').click();await active(page).locator('.room-v021').waitFor();}
async function snapshot(page){return page.evaluate(()=>PlayroomAppBridge.roomService.snapshot(PlayroomAppBridge.room().id));}

