 await startRoom(page,'uno');const roomBefore=await snapshot(page);await active(page).locator('[data-command=room-rules]').click();const form=active(page).locator('#room-rules-form'),card=form.locator('[data-rule-field=preset]'),next=card.locator('[data-rule-next]');assert.equal(await next.evaluate(n=>n.tagName),'BUTTON');assert.equal(await card.getAttribute('role'),null);
